INSERT INTO `api_disertante` VALUES
(19,'Agustin Varamo','En un mercado laboral en constante evolución, la empleabilidad se ha convertido en un factor clave para el éxito profesional. Esta charla te brindará las herramientas prácticas y estratégicas para fortalecer tu perfil y destacar en el mundo profesional.','ponencias/agustin-varamo.png','Empleabilidad',NULL,'https://www.linkedin.com/in/agustinvaramo','ponencias/agustin-varamo_Mlw4cnC.png'),
(20,'Jorge Golfieri','Descubrí cómo un simulador ferroviario permite entrenar, planificar y optimizar operaciones ferroviarias, combinando realismo y tecnología avanzada.','ponencias/jorge-golfieri.png','Simulador ferroviario',NULL,'https://www.linkedin.com/in/jorge-golfieri-07b638b?lipi=urn%3Ali%3Apage%3Ad_flagship3_profile_view_base_contact_details%3BLoXicdquTmOCLwseaIUPug%3D%3D',NULL),
(21,'Juan Sanchez','Una mirada actual sobre los desafíos y problemáticas que enfrentan los mandos medios en Argentina, explorando sus roles, tensiones y oportunidades de liderazgo.','ponencias/juan-sanchez.png','Mandos Rotos: Charla actual sobre la problemáticas de los Mandos Medios en Argentina',NULL,'https://www.linkedin.com/in/jmsanchez-lastmile',NULL),
(22,'Martin Boris','La charla mostrará cómo la tecnología está revolucionando la última milla, permitiendo mayor precisión, trazabilidad y eficiencia en las entregas.','ponencias/martin-boris.png','Revolucioná tu Logística: Última Milla con Tecnología y Precisión',NULL,'https://www.linkedin.com/in/boris-martin-15554717a?lipi=urn%3Ali%3Apage%3Ad_flagship3_profile_view_base_contact_details%3BrgRePl1zRrWrA60ddhbGGg%3D%3D',NULL),
(23,'Gabriel Luchessi','Se abordará el papel del marketing como herramienta clave para comunicar y poner en valor la logística dentro de las organizaciones y hacia los clientes.','ponencias/gabriel-luchessi.png','Marketing: el desafío de explicar la logística',NULL,'http://linkedin.com/in/gabriellucchesi',NULL),
(24,'Delfina Salgado','Descubrí cómo la Logística 4.0 y la tecnología avanzada están transformando la cadena de suministro, optimizando procesos y potenciando la eficiencia en cada eslabón.','ponencias/delfina-salgado.png','Logística 4.0: Redefiniendo la Eficiencia en la Cadena de Suministro con Tecnología Avanzada',NULL,'https://www.linkedin.com/in/delfinalucerosalgado',NULL),
(25,'Federico Carlos','Exploramos los desafíos y oportunidades de la logística portuaria e intermodal, destacando cómo la coordinación entre distintos modos de transporte optimiza la cadena de suministro.','ponencias/federico-carlos.png','Logística Portuaria e Intermodal.',NULL,'http://linkedin.com/in/federico-carlos-75a44b80',NULL),
(27,'Cristian Ruiz','Explorá cómo la inteligencia artificial, la automatización y los sistemas a medida están transformando la logística, optimizando procesos y redefiniendo la cadena de valor.','ponencias/cristian-ruiz.png','El Futuro de la Logística: IA, Automatización y Sistemas a Medida',NULL,'https://www.linkedin.com/in/cristian-facundo-ruiz-diaz-92b766a0?lipi=urn%3Ali%3Apage%3Ad_flagship3_profile_view_base_contact_details%3Bh0VuzCHfTrijzKLn3TPN4Q%3D%3D',NULL),
(28,'Natalia Gonzalez','La charla propone un recorrido sobre la transformación del rol de los conductores de carga en la Argentina, desde una actividad tradicionalmente vista como un oficio hacia una profesión enmarcada en mayores exigencias técnicas, tecnológicas y de seguridad.','ponencias/natalia-gonzalez.png','\"Del oficio a la profesión: La nueva era de los conductores de carga en Argentina\"',NULL,'https://www.linkedin.com/in/natalia-gonzalez-weiber',NULL),
(29,'Alexander Machado','Descubrí cómo Lean Supply Chain 4.0 combina eficiencia sin desperdicio, visibilidad en tiempo real y resiliencia, utilizando tecnología avanzada para optimizar toda la cadena de suministro.','ponencias/alexander-machado.png','Lean Supply Chain 4.0- Eficiencia sin desperdicio, visibilidad en tiempo real y resiliencia impulsada por la tecnología',NULL,'https://www.linkedin.com/in/alexander-cardozo-machado-5612b442',NULL),
(30,'Felipe Rios','La charla abordará la evolución del comercio exterior argentino, analizando su recorrido histórico, la situación actual y las perspectivas a futuro en un escenario marcado por la desregulación.','ponencias/felipe-rios.png','Situación del Comercio Exterior Argentino: Pasado, Presente y Futuro en un Contexto de Desregulación',NULL,'https://www.linkedin.com/in/felipe-ezequiel-r-84b70b142?lipi=urn%3Ali%3Apage%3Ad_flagship3_profile_view_base_contact_details%3B%2FOXcg8XMQOmU5S1vz73Crw%3D%3D',NULL),
(31,'Claudia Freed','Se explorará cómo la logística y las cadenas de suministro se están adaptando a los principios de la economía circular, impulsando modelos más sostenibles y eficientes.','ponencias/claudia-freed.png','Futuro de la logistica/cadenas de suministros y la economia circular.',NULL,'https://www.linkedin.com/in/claudiafreed',NULL),
